(lambda _: kAssert(kEq(list(map(lambda x: kMul(x, 2), [1, 2, 3])), [2, 4, 6])))(None)
(lambda _: kAssert(kEq(list(map(lambda s: kAdd(s, "!"), ["a", "b"])), ["a!", "b!"])))(None)
(lambda _: kAssert(kEq(list(map(lambda x: kMul(x, 2), [1, 2, 3])), [2, 4, 6])))(None)
(lambda _: kAssert(kEq(list(map(lambda x: kAdd(x, 10), [1, 2, 3])), [11, 12, 13])))(None)
(lambda _: kAssert(kEq((double := lambda x: kMul(x, 2), double(5))[-1], 10)))(None)
(lambda _: kAssert(kEq((add1 := lambda x: kAdd(x, 1), list(map(add1, [1, 2, 3])))[-1], [2, 3, 4])))(None)
